// Package codegen generates typed Go and TypeScript code from a compiled schema: one struct or interface per
// content type, named groups, enums, and a typed handle per type for hooks and the Local API.
package codegen

import (
	"cmp"
	"fmt"
	"slices"

	"github.com/hydrogencms/hydrogen/core/schema"
)

const header = "Code generated by hydrogen. DO NOT EDIT."

// names records every top-level identifier a generated file set declares, to report collisions.
type names struct {
	owner map[string]string
}

func newNames(reserved ...string) *names {
	n := &names{owner: map[string]string{}}
	for _, r := range reserved {
		n.owner[r] = "a generated helper"
	}
	return n
}

// declare claims id for what (a human description such as `field "address" of type "article"`).
func (n *names) declare(id, what string) error {
	if prev, ok := n.owner[id]; ok {
		return fmt.Errorf("codegen: identifier %s is generated for both %s and %s; rename one of them", id, prev, what)
	}
	n.owner[id] = what
	return nil
}

func sortedTypes(types []*schema.Type) []*schema.Type {
	out := slices.Clone(types)
	slices.SortStableFunc(out, func(a, b *schema.Type) int { return cmp.Compare(a.Name, b.Name) })
	return out
}

func sortedGroups(groups []*schema.Group) []*schema.Group {
	out := slices.Clone(groups)
	slices.SortStableFunc(out, func(a, b *schema.Group) int { return cmp.Compare(a.Name, b.Name) })
	return out
}

// optional reports whether a field may be absent.
func optional(f *schema.Field) bool { return !f.Required || f.When != nil }

func checkName(kind, name string) error {
	if !validSchemaName(name) {
		return fmt.Errorf("codegen: invalid %s name %q (use letters, digits, '_' and '-')", kind, name)
	}
	return nil
}

// groupSet validates group names and returns them by name.
func groupSet(groups []*schema.Group) (map[string]*schema.Group, error) {
	m := make(map[string]*schema.Group, len(groups))
	for _, g := range groups {
		if err := checkName("group", g.Name); err != nil {
			return nil, err
		}
		if m[g.Name] != nil {
			return nil, fmt.Errorf("codegen: group %q is defined twice", g.Name)
		}
		m[g.Name] = g
	}
	return m, nil
}

func checkTypes(types []*schema.Type) error {
	seen := map[string]bool{}
	for _, t := range types {
		if err := checkName("type", t.Name); err != nil {
			return err
		}
		if seen[t.Name] {
			return fmt.Errorf("codegen: type %q is defined twice", t.Name)
		}
		seen[t.Name] = true
	}
	return nil
}
